def infer(expr, schema, params=None):
    expr.type = _infer(expr, schema, params or {})
    return expr.type


def _infer(expr, schema, params):
    if isinstance(expr, Literal):
        return expr.type
    if isinstance(expr, ColumnRef):
        if expr.name not in schema:
            raise TypeCheckError(f"line {expr.line}: unknown column '{expr.name}'")
        return schema[expr.name]
    if isinstance(expr, Unary):
        t = infer(expr.operand, schema, params)
        if expr.op == "!":
            if t != dtypes.BOOL:
                raise TypeCheckError(f"line {expr.line}: '!' requires a boolean operand, got {t}")
            return dtypes.BOOL
        if not dtypes.is_numeric(t):
            raise TypeCheckError(f"line {expr.line}: unary '{expr.op}' requires a number, got {t}")
        return t
    if isinstance(expr, Binary):
        return _infer_binary(expr, schema, params)
    if isinstance(expr, InExpr):
        return _infer_in(expr, schema, params)
    if isinstance(expr, Cast):
        source = infer(expr.operand, schema, params)
        if not casts.allowed(source, expr.target):
            raise TypeCheckError(f"line {expr.line}: cannot cast {source} to {expr.target}")
        return expr.target
    if isinstance(expr, Call):
        return _infer_call(expr, schema, params)
    raise AssertionError(f"unknown expression node {expr!r}")


def _infer_call(expr, schema, params):
    if expr.name == "param":
        name = expr.args[0].value
        if name not in params:
            raise DSLSyntaxError(f"line {expr.line}: unknown parameter '{name}'")
        expr.args[0].type = dtypes.STRING
        return params[name].type
    arg_types = [infer(a, schema, params) for a in expr.args]
    if expr.name in functions.WINDOW_FUNCTIONS:
        if arg_types[1] != dtypes.INT:
            raise TypeCheckError(f"line {expr.line}: {expr.name}() offset must be an int, "
                                 f"got {arg_types[1]}")
        return arg_types[0]
    return functions.result_type(expr.name, arg_types, expr.line)


def _infer_binary(expr, schema, params):
    lt = infer(expr.left, schema, params)
    rt = infer(expr.right, schema, params)
    op = expr.op
    if op in LOGICAL_OPS:
        if lt != dtypes.BOOL or rt != dtypes.BOOL:
            raise TypeCheckError(f"line {expr.line}: '{op}' requires boolean operands, "
                                 f"got {lt} and {rt}")
        return dtypes.BOOL
    if op in COMPARISON_OPS:
        if not dtypes.comparable(lt, rt, op):
            raise TypeCheckError(f"line {expr.line}: cannot compare {lt} with {rt} using '{op}'")
        return dtypes.BOOL
    if op in ARITHMETIC_OPS:
        if not (dtypes.is_numeric(lt) and dtypes.is_numeric(rt)):
            raise TypeCheckError(f"line {expr.line}: '{op}' requires numeric operands, "
                                 f"got {lt} and {rt}")
        if op == "/":
            return dtypes.FLOAT
        return dtypes.numeric_result(lt, rt)
    raise AssertionError(f"unknown operator {op}")


def _infer_in(expr, schema, params):
    nt = infer(expr.needle, schema, params)
    ht = infer(expr.haystack, schema, params)
    if not (isinstance(expr.needle, Literal) and nt == dtypes.STRING):
        raise TypeCheckError(f"line {expr.line}: left side of 'in' must be a string literal")
    if not (isinstance(expr.haystack, ColumnRef) and ht == dtypes.STRING):
        raise TypeCheckError(f"line {expr.line}: right side of 'in' must be a string column")
    return dtypes.BOOL

"""Pipeline parameters: merging DSL defaults with --param values into typed constants."""
import re

from . import dtypes
from .errors import DSLSyntaxError, IOFailure, TypeCheckError

_INT_RE = re.compile(r"^[+-]?\d+$")
_FLOAT_RE = re.compile(r"^[+-]?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$")
_BOOLS = {"true": True, "false": False}


class ParamValue:
    def __init__(self, name, param_type, value):
        self.name = name
        self.type = param_type
        self.value = value


def parse_cli_params(items):
    """Turn ['key=value', ...] into a dict; the last duplicate wins."""
    values = {}
    for item in items:
        key, sep, value = item.partition("=")
        key = key.strip()
        if not sep or not key:
            raise IOFailure(f"invalid --param '{item}': expected key=value")
        values[key] = value
    return values


def check_provided(decls, cli_values, strict=False):
    """DSL errors: parameters without a default that were not supplied (and, in
    strict mode, supplied parameters the pipeline does not declare)."""
    missing = [d.name for d in decls if d.default is None and d.name not in cli_values]
    if missing:
        raise DSLSyntaxError(f"missing value for parameter(s) without default: "
                             f"{', '.join(missing)}")
    if strict:
        declared = {d.name for d in decls}
        unknown = sorted(k for k in cli_values if k not in declared)
        if unknown:
            raise DSLSyntaxError(f"undeclared parameter(s) supplied: {', '.join(unknown)}")


def resolve(decls, cli_values, ts_parser):
    """Return name -> ParamValue; values that do not fit their type are type errors."""
    resolved = {}
    for decl in decls:
        param_type = decl.type
        if param_type is None:
            param_type = decl.default.type if decl.default is not None else dtypes.STRING
        default = None
        if decl.default is not None:
            default = _from_literal(decl, param_type, ts_parser)
        if decl.name in cli_values:
            value = _from_text(decl.name, param_type, cli_values[decl.name], ts_parser)
        else:
            value = default
        resolved[decl.name] = ParamValue(decl.name, param_type, value)
    return resolved


def _from_literal(decl, param_type, ts_parser):
    lit = decl.default
    if lit.type == param_type:
        return lit.value
    if param_type == dtypes.FLOAT and lit.type == dtypes.INT:
        return float(lit.value)
    if param_type == dtypes.TIMESTAMP and lit.type == dtypes.STRING:
        try:
            return ts_parser.parse(lit.value)
        except ValueError as exc:
            raise TypeCheckError(f"line {decl.line}: default of parameter '{decl.name}' is not "
                                 f"a valid timestamp: {exc}") from exc
    raise TypeCheckError(f"line {decl.line}: default of parameter '{decl.name}' has type "
                         f"{lit.type}, expected {param_type}")


def _from_text(name, param_type, text, ts_parser):
    def fail(detail=""):
        raise TypeCheckError(f"--param {name}={text!r} is not a valid {param_type}{detail}")

    raw = text.strip()
    if param_type == dtypes.STRING:
        return text
    if param_type == dtypes.INT:
        if not _INT_RE.match(raw):
            fail()
        return int(raw)
    if param_type == dtypes.FLOAT:
        if not _FLOAT_RE.match(raw):
            fail()
        value = float(raw)
        if value != value or value in (float("inf"), float("-inf")):
            fail()
        return value
    if param_type == dtypes.BOOL:
        if raw.lower() not in _BOOLS:
            fail()
        return _BOOLS[raw.lower()]
    if param_type == dtypes.TIMESTAMP:
        try:
            return ts_parser.parse(raw)
        except ValueError as exc:
            fail(f": {exc}")
    raise AssertionError(f"unhandled parameter type {param_type}")

